import path from "node:path";
import { beforeAll, describe, expect, it } from "vitest";
import { CONFIGS } from "@/lib/reports/configs";
import type { ReportDocument } from "@/lib/reports/types";
import { FIXTURES, parseFile } from "./helpers";

// Workbooks generated by src/lib/reports/guide/report_kit.py. They lock the
// contract between the kit and the parser: if a parser change breaks them,
// change report_kit.py too and regenerate both files (docs/reports.md).
const KIT_REGISTRATION = path.join(FIXTURES, "Kit_ICY_S26_Registration_Form_Analysis.xlsx");
const KIT_FEEDBACK = path.join(FIXTURES, "Kit_Test_S26_Feedback_Form_Analysis.xlsx");

const EMAIL = /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+\.[A-Za-z]{2,}/;

const cases = [
  {
    file: KIT_REGISTRATION,
    type: "registration" as const,
    meta: { eventName: "ICY S'26", period: "23 May – 6 Jun", sampleSize: 424 },
    keys: ["overview", "trend", "channels", "audience", "patterns", "tables", "methodology"],
    snapshot: "__snapshots__/kit-registration.json",
  },
  {
    file: KIT_FEEDBACK,
    type: "feedback" as const,
    meta: { eventName: "TEST S'26", period: "29 Aug – 3 Sep", sampleSize: 60 },
    keys: ["overview", "themes", "scorecard", "segments", "patterns", "methodology"],
    snapshot: "__snapshots__/kit-feedback.json",
  },
];

describe.each(cases)("report kit · $type", (c) => {
  let doc: ReportDocument;
  beforeAll(async () => {
    doc = await parseFile(c.file);
  });

  it("parses with no warnings, with type and meta from the header", () => {
    expect(doc.warnings).toEqual([]);
    expect(doc.type).toBe(c.type);
    expect(doc.meta).toEqual(c.meta);
  });

  it("has every configured sheet, in order", () => {
    expect(doc.sheets.map((s) => s.key)).toEqual(c.keys);
    expect(doc.sheets.map((s) => s.key)).toEqual(CONFIGS[c.type].sheets.map((s) => s.key));
  });

  it("has every expected section from the config", () => {
    for (const sc of CONFIGS[c.type].sheets) {
      const titles = doc.sheets.find((s) => s.key === sc.key)!.sections.map((s) => s.title);
      for (const re of sc.expect ?? []) expect(titles.some((t) => re.test(t)), `${sc.key}: ${re}`).toBe(true);
    }
  });

  it("carries no e-mail in any parsed cell", () => {
    expect(JSON.stringify(doc)).not.toMatch(EMAIL);
  });

  // Golden snapshot, like the Özge fixtures (update with: npx vitest run -u).
  it("matches the golden snapshot", async () => {
    await expect(JSON.stringify(doc, null, 2)).toMatchFileSnapshot(c.snapshot);
  });
});
